-- gap cmp:67:9:1, written by an automated writer
test("breakit Drive.Cut: Bea's saved shift log names Anita as the caster, not herself", function()
	local w = T.H.NewWorld({})
	local names = { "Ana Smith", "Bea Jones", "Cal Brown" }
	local function key(n) return (n:lower():gsub("[%s%-]+", " ")) end
	local cs = {}
	for i, name in ipairs(names) do
		local crew = {}
		for _, n in ipairs(names) do
			if n ~= name then crew[#crew + 1] = { name = n, role = "lock", app = true } end
		end
		cs[i] = w:addClient(name, { spot = "Undercity", class = "WARLOCK", saved = { Wuber = { chars = { [key(name)] = { crew = crew, captain = (i == 1) and "" or "Ana Smith", wizard = true } } } } })
		cs[i].W.VERSION = "2.3.0"
	end
	w:addBot("Dan Miller", { spot = "Orgrimmar" })
	w:group({ "Ana Smith", "Bea Jones", "Cal Brown", "Dan Miller" })
	w:advance(1)
	local ana, bea = cs[1], cs[2]
	ana.W.Drive.SetOpen(true)
	w:advance(3)
	ana.W.Drive.Do("CAST", "Dan Miller")
	w:advance(1)
	bea.W.Drive.Do("HELP", "Dan Miller")
	w:advance(1)
	ana.W.Drive.Do("END", "Dan Miller", 1)
	w:advance(1)
	ana.W.Drive.SetOpen(false)
	w:advance(3)
	local log = bea.W.db.drive.log.cut
	ok(type(log) == "table" and #log == 1, "Bea's window keeps one shift log entry")
	local e = (type(log) == "table" and log[1]) or {}
	eq((e.casts or {})["Ana Smith"], 1, "the cast is saved under Anita's name")
	eq((e.clicks or {})["Bea Jones"], 1, "the click is saved under Bea's name")
	T.clean(w)
end)

