test("breakit Drive.Cut: a full shift log keeps its cap and drops only the oldest shift", function()
	local w = T.H.NewWorld({})
	local saved = function(me, other, cap)
		return { Wuber = { chars = { [me:lower()] = { crew = { { name = other, role = "lock", app = true } }, captain = cap, wizard = true } } } }
	end
	local ana = w:addClient("Ana Smith", { spot = "Undercity", class = "WARLOCK", saved = saved("Ana Smith", "Bea Jones", "") })
	local bea = w:addClient("Bea Jones", { spot = "Undercity", class = "WARLOCK", saved = saved("Bea Jones", "Ana Smith", "Ana Smith") })
	ana.W.VERSION = "2.3.0"
	bea.W.VERSION = "2.3.0"
	w:addBot("Dan Miller", { spot = "Orgrimmar" })
	w:group({ "Ana Smith", "Bea Jones", "Dan Miller" })
	T.settle(w)
	local max = ana.W.Drive.CUT_LOG_MAX
	local full = {}
	for i = 1, max do full[i] = { at = i, gold = 1, casts = {}, clicks = {}, rule = "clicks", pct = 40 } end
	ana.W.db.drive.log.cut = full
	ana.W.Drive.SetOpen(true)
	w:advance(3)
	ana.W.Drive.Do("PAID", "Dan Miller", 5000)
	w:advance(1)
	ana.W.Drive.SetOpen(false)
	w:advance(3)
	local log = ana.W.db.drive.log.cut
	eq(#log, max, "the log is kept at its cap after one more shift")
	eq(log[#log].gold, 5000, "the newest shift is last")
	eq(log[1].gold, 1, "the oldest shift that was kept is still first")
	T.clean(w)
end)

